from django.db import migrations, models


def to_months_and_test_prices(apps, schema_editor):
    """Packages now count in months; and while Pesapal is being tested, prices are tiny and a month is 3 days.
    Change both in the dashboard when testing is over (Site Settings > Days in one month = 30, real prices)."""
    AdPackage, Plan, SiteSetting = apps.get_model("core", "AdPackage"), apps.get_model("core", "Plan"), apps.get_model("core", "SiteSetting")
    for p in AdPackage.objects.all():
        p.months = max(1, round(p.days / 30))
        p.features = p.features.replace("for 30 days", "for 1 month").replace("Runs for 60 days", "Runs for 2 months")
        p.save(update_fields=["months", "features"])
    for slug, price in [("starter", 50), ("featured", 100), ("spotlight", 150)]:
        AdPackage.objects.filter(slug=slug).update(price=price)
    for name, price in [("Basic", 50), ("Silver", 100), ("Gold", 150), ("Tanzanite", 200)]:
        Plan.objects.filter(name=name).update(price=price)
    SiteSetting.objects.update(days_per_month=3)


